const products = [
  {id:'tee',name:'TerraWeave Tee',category:'apparel',categoryLabel:'APPAREL / 001',price:'AED 129',score:82,badge:'SOURCE SIGNAL DEMO*',art:'👕',description:'A soft everyday tee made for the fictional Orbital Goods collection. Its cotton sourcing claim is paired with a vegetation-change signal from the declared growing region.',evidence:[['Declared source region','Gujarat, India · example'],['Vegetation signal','Stable in demo time series'],['Facility heat context','Within example baseline'],['Documentation gap','Farm chain of custody pending']],model:'models/terraweave-tee.obj'},
  {id:'bottle',name:'Orbit Refill Bottle',category:'everyday',categoryLabel:'EVERYDAY / 002',price:'AED 89',score:76,badge:'EVIDENCE IN REVIEW*',art:'✦',description:'A reusable bottle concept that makes its manufacturing and warehouse footprint visible. Product materials and shipping emissions still need supplier records.',evidence:[['Declared facility','Dubai, UAE · example'],['Warehouse heat signal','Within example baseline'],['Offset forest signal','Growth observed in demo'],['Documentation gap','Material origin pending']],model:'models/orbit-refill-bottle.obj'},
  {id:'lamp',name:'Canopy Desk Lamp',category:'home',categoryLabel:'HOME / 003',price:'AED 249',score:71,badge:'EVIDENCE IN REVIEW*',art:'◈',description:'A compact desk lamp concept with a timber sourcing region that can be watched for forest cover change. Timber certification remains a separate requirement.',evidence:[['Declared source region','Central Kalimantan · example'],['Forest cover signal','No loss in demo scenario'],['Offset forest signal','Growth observed in demo'],['Documentation gap','Timber certification pending']],model:'models/canopy-desk-lamp.obj'}
];
const scenarios={
 baseline:{forest:82,heat:72,offset:78,reason:'Three observable signals support the claim. Supplier provenance still needs independent documentation.',details:['Vegetation stable in declared sourcing zone','Surface heat within local comparison band','Forest canopy signal improving']},
 forest:{forest:28,heat:72,offset:78,reason:'A sourcing-zone vegetation anomaly needs investigation before this claim can be trusted.',details:['Vegetation loss flagged near declared source','Surface heat within local comparison band','Forest canopy signal improving']},
 heat:{forest:82,heat:25,offset:78,reason:'A facility heat anomaly lowers confidence in the warehouse efficiency claim.',details:['Vegetation stable in declared sourcing zone','Surface heat above local comparison band','Forest canopy signal improving']},
 offset:{forest:82,heat:72,offset:18,reason:'Offset forest growth has stalled in this scenario. Carbon credit quality needs separate review.',details:['Vegetation stable in declared sourcing zone','Surface heat within local comparison band','Canopy growth trend stalled']}
};
const metricNames=[['Sourcing vegetation',.4],['Warehouse heat',.25],['Offset forest growth',.35]];
let currentFilter='all', currentProduct=null, viewer=null, currentScenario='baseline', anomalyResults=null;
const q=s=>document.querySelector(s);
function renderProducts(){q('#product-grid').innerHTML=products.filter(p=>currentFilter==='all'||p.category===currentFilter).map(p=>`<button class="product-card" data-product="${p.id}" aria-label="Open ${p.name} product details"><div class="product-visual"><span class="product-badge">${p.badge}</span><span class="product-art" aria-hidden="true">${p.art}</span><span class="product-index">${p.categoryLabel}</span></div><div class="product-content"><div class="product-meta"><span>ORBITAL GOODS</span><span>3D VIEW ↗</span></div><h3>${p.name}</h3><p>${p.description.slice(0,98)}…</p><div class="product-bottom"><b>${p.price}</b><span>TRUST ${p.score}/100 ↗</span></div></div></button>`).join('');document.querySelectorAll('[data-product]').forEach(el=>el.addEventListener('click',()=>openProduct(el.dataset.product)))}
function renderScore(key){currentScenario=key;const s=scenarios[key],score=Math.round(s.forest*.4+s.heat*.25+s.offset*.35);q('#score-number').textContent=score;q('#score-label').textContent=score>=75?'Promising, with gaps':score>=55?'Needs investigation':'Claim at risk';q('#score-summary').textContent=s.reason;const values=[s.forest,s.heat,s.offset];q('#metric-list').innerHTML=metricNames.map(([name],i)=>`<div class="metric"><span class="metric-name">${name}</span><span class="metric-value">${values[i]}/100</span><div class="metric-bar"><i style="width:${values[i]}%;background:${values[i]<50?'#e5c77c':'#cbf485'}"></i></div><span class="metric-desc">${s.details[i]}</span></div>`).join('');document.querySelectorAll('.scenario').forEach(el=>el.classList.toggle('active',el.dataset.scenario===key));q('.score-ring').style.borderColor=score<55?'#e5c77c':'#cbf485';renderAnomalyAlert()}
function renderAnomalyAlert(){const el=q('#ai-alert');if(!anomalyResults){el.textContent='Loading anomaly model result…';return}const names={baseline:'baseline_evidence',forest:'forest_loss',heat:'warehouse_heat_spike',offset:'offset_growth_stalls'};const result=anomalyResults.find(x=>x.scenario===names[currentScenario]);if(!result)return;el.innerHTML=result.anomaly?`<b>✦ MODEL ALERT</b><span>Unusual ${result.dominant_signal} signal detected · kNN distance ${result.anomaly_score} (threshold ${result.threshold})</span>`:`<b>✦ MODEL SIGNAL</b><span>No anomaly detected in the synthetic baseline · kNN distance ${result.anomaly_score}</span>`;el.classList.toggle('alert',result.anomaly)}
function openProduct(id){currentProduct=products.find(p=>p.id===id);const p=currentProduct;if(!p)return;q('#dialog-title').textContent=p.name;q('#dialog-description').textContent=p.description;q('#dialog-price').textContent=p.price;q('#dialog-score').textContent=`GREEN TRUST ${p.score}/100*`;q('#dialog-evidence').innerHTML=p.evidence.map(([k,v])=>`<div class="evidence-item"><span>${k}</span><span>${v}</span></div>`).join('');q('#model-download').href=p.model;q('#product-dialog').showModal();document.body.style.overflow='hidden';initViewer(p.id)}
function closeProduct(){q('#product-dialog').close();document.body.style.overflow='';if(viewer){viewer.dispose();viewer=null}}
function createMarker(color){return L.divIcon({html:`<div class="map-marker" style="background:${color}"></div>`,iconSize:[20,20],iconAnchor:[10,10],className:''})}
function initMap(){if(!window.L){q('.map-fallback').innerHTML='Map unavailable<small>Satellite layer needs an internet connection.</small>';return}const map=L.map('map',{scrollWheelZoom:false,zoomControl:true}).setView([22,62],4);q('.map-fallback')?.remove();const base=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap contributors'}).addTo(map);const sat=L.tileLayer('https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/MODIS_Terra_CorrectedReflectance_TrueColor/default/2024-09-01/GoogleMapsCompatible_Level9/{z}/{y}/{x}.jpg',{maxZoom:9,opacity:.82,attribution:'NASA GIBS / MODIS Terra'}).addTo(map);L.control.layers({'OpenStreetMap':base},{'NASA satellite imagery':sat},{collapsed:true}).addTo(map);[[23.02,72.57,'#cbf485','Example cotton sourcing zone · Gujarat, India'],[25.2,55.27,'#7cdbdf','Example fulfillment facility · Dubai, UAE'],[-1.2,113.8,'#e5c77c','Example offset forest zone · Kalimantan, Indonesia']].forEach(([lat,lon,color,label])=>L.marker([lat,lon],{icon:createMarker(color)}).addTo(map).bindPopup(label));setTimeout(()=>map.invalidateSize(),200)}
async function initViewer(id){const container=q('#model-container');container.innerHTML='<div class="model-placeholder">✦</div>';try{const THREE=await import('https://unpkg.com/three@0.160.0/build/three.module.js');if(!q('#product-dialog').open||currentProduct?.id!==id)return;container.innerHTML='';const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(38,1,.1,100);camera.position.set(0,1.4,6.3);const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;container.appendChild(renderer.domElement);scene.add(new THREE.AmbientLight(0xffffff,2.3));const light=new THREE.DirectionalLight(0xffffff,3.8);light.position.set(-3,6,6);scene.add(light);const rim=new THREE.DirectionalLight(0x91ffd9,3);rim.position.set(4,2,-4);scene.add(rim);const group=new THREE.Group();scene.add(group);const mat=(color,metalness=0)=>new THREE.MeshStandardMaterial({color,metalness,roughness:.42,side:THREE.DoubleSide});const add=(geo,m,x=0,y=0,z=0,rx=0,ry=0,rz=0)=>{const mesh=new THREE.Mesh(geo,m);mesh.position.set(x,y,z);mesh.rotation.set(rx,ry,rz);group.add(mesh);return mesh};if(id==='tee'){const cloth=mat(0xc4d9c0),neck=mat(0x0a282b);const shape=new THREE.Shape();[[-1.05,1.4],[-.45,1.65],[-.28,1.3],[.28,1.3],[.45,1.65],[1.05,1.4],[1.42,.6],[.95,.42],[.78,.75],[.78,-1.5],[-.78,-1.5],[-.78,.75],[-.95,.42],[-1.42,.6]].forEach(([x,y],i)=>i?shape.lineTo(x,y):shape.moveTo(x,y));shape.closePath();add(new THREE.ExtrudeGeometry(shape,{depth:.18,bevelEnabled:true,bevelThickness:.08,bevelSize:.06,bevelSegments:2}),cloth,0,0,-.1);add(new THREE.TorusGeometry(.31,.055,12,36,Math.PI),neck,0,1.31,.16,0,0,Math.PI);add(new THREE.CircleGeometry(.16,5),mat(0x8fab71),0,.32,.19)}else if(id==='bottle'){const body=mat(0x9abfb3,.65),dark=mat(0x1b3d3c,.7),cap=mat(0xc9dba8,.25);add(new THREE.CylinderGeometry(.62,.72,2.45,48),body,0,-.15);add(new THREE.CylinderGeometry(.37,.37,.33,48),dark,0,1.25);add(new THREE.CylinderGeometry(.43,.43,.25,48),cap,0,1.48);add(new THREE.TorusGeometry(.31,.06,12,48),cap,0,1.75,0,Math.PI/2);add(new THREE.TorusGeometry(.66,.017,8,48),dark,0,-.85);add(new THREE.CircleGeometry(.2,6),mat(0xe1eed0),0,.16,.63)}else{const wood=mat(0x947b55),metal=mat(0xb4c8ab,.38),glow=mat(0xe8e3af);add(new THREE.CylinderGeometry(.7,.85,.19,48),wood,0,-1.35);add(new THREE.CylinderGeometry(.08,.08,2.2,24),metal,0,-.25);add(new THREE.SphereGeometry(.12,16,16),metal,0,.82);add(new THREE.CylinderGeometry(.35,.98,.85,48,1,true),metal,0,1.1);add(new THREE.CircleGeometry(.96,48),glow,0,.68,0,Math.PI/2);add(new THREE.CylinderGeometry(.12,.12,.12,24),wood,0,1.58)}group.rotation.y=-.32;let dragging=false,previous=0,frame;const resize=()=>{const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()};resize();const observer=new ResizeObserver(resize);observer.observe(container);const down=e=>{dragging=true;previous=e.clientX;container.setPointerCapture(e.pointerId)},move=e=>{if(dragging){group.rotation.y+=(e.clientX-previous)*.01;previous=e.clientX}},up=()=>dragging=false;container.addEventListener('pointerdown',down);container.addEventListener('pointermove',move);container.addEventListener('pointerup',up);const animate=()=>{frame=requestAnimationFrame(animate);if(!dragging)group.rotation.y+=.003;renderer.render(scene,camera)};animate();viewer={rotate:d=>group.rotation.y+=d,dispose:()=>{cancelAnimationFrame(frame);observer.disconnect();renderer.dispose();container.innerHTML=''}}}catch(e){container.innerHTML=`<div class="model-placeholder" role="img" aria-label="${currentProduct.name} model preview">${currentProduct.art}</div>`}}
document.querySelectorAll('.filter').forEach(el=>el.addEventListener('click',()=>{currentFilter=el.dataset.filter;document.querySelectorAll('.filter').forEach(b=>b.classList.toggle('active',b===el));renderProducts()}));document.querySelectorAll('.scenario').forEach(el=>el.addEventListener('click',()=>renderScore(el.dataset.scenario)));q('.dialog-close').addEventListener('click',closeProduct);q('#product-dialog').addEventListener('click',e=>{if(e.target===q('#product-dialog'))closeProduct()});q('#product-dialog').addEventListener('close',()=>{document.body.style.overflow='';if(viewer){viewer.dispose();viewer=null}});q('#rotate-left').addEventListener('click',()=>viewer?.rotate(-.4));q('#rotate-right').addEventListener('click',()=>viewer?.rotate(.4));q('#detail-action').addEventListener('click',()=>{closeProduct();q('#intelligence').scrollIntoView({behavior:'smooth'})});q('.menu-toggle').addEventListener('click',()=>{const nav=q('.site-header nav');const open=nav.classList.toggle('open');q('.menu-toggle').setAttribute('aria-expanded',open)});document.querySelectorAll('.site-header nav a').forEach(a=>a.addEventListener('click',()=>q('.site-header nav').classList.remove('open')));renderProducts();renderScore('baseline');fetch('data/anomaly_results.json').then(r=>r.json()).then(data=>{anomalyResults=data.results;renderAnomalyAlert()}).catch(()=>{q('#ai-alert').textContent='Anomaly model output unavailable.'});window.addEventListener('load',initMap);
